import {clone,sortFrames,linearFrames,treeFrames,makeTree,treeValues,height,balance,hashFrames,parseGraph,graphFrames,dpFrames} from './algorithms.js';
const $=id=>document.getElementById(id);
const sorts={
 bubble:['Bubble Sort','Compare neighbors. Swap when needed. Watch the largest values bubble to the end.','O(n²)','O(1)','Stable','A small swap can make a big difference.','Repeatedly compare adjacent values and swap them if they are out of order. After each pass, the largest unsorted value is in its final place. An early exit stops the algorithm when a pass makes no swaps.','Load an already sorted list. How many comparisons does the early-exit version need?','An array with n values needs at most n − 1 passes. Each pass settles one more value.',['for each pass in array:','  compare adjacent values','  if left > right: swap them','  stop if no swaps in this pass','return sorted_array']],
 selection:['Selection Sort','Find the smallest remaining value and move it into place.','O(n²)','O(1)','Unstable','One choice, one settled position.','Scan the unsorted section to find its minimum. Swap it into the first unsorted position, then repeat on the smaller remaining section.','Try duplicate values. Selection sort can change the relative order of equal elements.','Selection sort makes few swaps, but still scans the remaining values on every pass.',['for each position i:','  find minimum in array[i:]','  swap array[i] with minimum','  mark position i as settled','return sorted_array']],
 insertion:['Insertion Sort','Grow a sorted prefix, one value at a time.','O(n²)','O(1)','Stable','Make room for the next idea.','Take the next unsorted value and move it left until it fits into the sorted prefix. This version uses adjacent swaps, making every move visible.','Compare a nearly sorted list with a reverse-sorted list. Which needs more moves?','Insertion sort is efficient on small or nearly sorted lists. Its best case takes O(n) time.',['for i from 1 to n − 1:','  compare with the left neighbor','  swap left while out of order','  extend the sorted prefix','return sorted_array']],
 merge:['Merge Sort','Split the problem. Sort the halves. Merge the answers.','O(n log n)','O(n)','Stable','Smaller problems, better structure.','Recursively divide the list into halves until each has one element. Merge sorted halves by taking the smaller front value. The highlighted writes rebuild each sorted section.','Try a list with many duplicates. Values from the left half are taken first when they tie.','Merge sort needs additional storage, but its O(n log n) time does not depend on input order.',['split array into two halves','recursively sort both halves','merge: write the next smallest value','finish the merged section','return sorted_array']],
 quick:['Quick Sort','Partition around a pivot, then sort each side.','O(n²) worst','O(n) worst','Unstable','Give every value a side.','Choose the last value as a pivot. Move smaller values to the left, put the pivot in its final position, then recursively sort the left and right sections.','Try sorted input. A last-element pivot creates very uneven partitions.','Average time is O(n log n). This last-element pivot implementation has a quadratic worst case.',['choose the last value as pivot','compare each value with pivot','swap smaller values to the left','place pivot; recurse on both sides','return sorted_array']],
 heap:['Heap Sort','Build a max heap and repeatedly extract its largest value.','O(n log n)','O(1)','Unstable','Bring the maximum to the top.','Arrange values as a max heap, where every parent is at least as large as its children. Swap the root with the last unsorted value, shrink the heap, and restore the heap property.','Load reverse-sorted values and compare the number of writes with selection sort.','The array represents a binary heap: the children of index i are 2i + 1 and 2i + 2.',['build a max heap','compare parent and child values','swap and restore heap order','move maximum to the sorted suffix','return sorted_array']],
 radix:['Radix Sort','Sort nonnegative values one digit at a time.','O(d(n + b))','O(n + b)','Stable','One digit at a time.','Distribute values into digit buckets from 0 to 9, starting with the ones place. Collect buckets in order and repeat for tens and hundreds. Stable passes preserve the work of earlier digits.','Try 170, 45, 75, 90, 802, 24, 2, 66. Watch the order after each digit pass.','Here b = 10 and d is the number of decimal digits. This lab accepts values from 0 to 999.',['for each digit, from right to left:','  distribute values into digit buckets','  collect buckets in stable order','  continue with the next digit','return sorted_array']],
 counting:['Counting Sort','Count occurrences, then rebuild the sequence in order.','O(n + k)','O(k)','Numeric values','Let frequency do the sorting.','Create a frequency entry for every possible value. Count each input, then write each value back as many times as it occurs. This value-only version does not track the identity of equal records.','Try 4, 2, 2, 8, 3, 3, 1. Repeated values are reconstructed from their counts.','Counting sort is useful when the value range k is small. This lab accepts integers from 0 to 999.',['create a frequency array','count each value in the input','write each value by its frequency','finish reconstructing the array','return sorted_array']]
};
const topics={
 array:{title:'Arrays',icon:'▦',tag:'Data structure',desc:'A row of possibilities. Access, insert, update, and explore by index.',time:'O(n)',space:'O(n)',property:'Indexed',detail:'search / insert',idea:'Every value has an address.',body:'An array stores an ordered sequence of values. Access by index is O(1); searching takes O(n). Inserting or deleting within the sequence shifts the values that follow it.',experiment:'Insert at position 0, then at the end. Notice how many values need to move.',insight:'Positions are zero-based. The first value has index 0; insertion also accepts the position after the last value.'},
 linked:{title:'Linked Lists',icon:'⊷',tag:'Data structure',desc:'Follow the pointers. Build, reverse, and explore a chain of nodes.',time:'O(n)',space:'O(n)',property:'Linked nodes',detail:'position search',idea:'A connection is all it takes.',body:'Each node contains a value and a pointer to its neighbor. A doubly linked list has a previous pointer too. A circular list links its tail back to the head. This lab shows the logical links and uses indexed controls to choose positions.',experiment:'Switch to Circular, insert a new tail, and watch the tail-to-head link. Then reverse the sequence.',insight:'Finding an indexed position takes O(n). Once a node is known, changing its local links takes O(1).'},
 bst:{title:'Binary Search Tree',icon:'⋔',tag:'Trees',desc:'Smaller to the left. Larger to the right. Follow the branches.',time:'O(h)',space:'O(n)',property:'Ordered',detail:'search / update',idea:'Order makes a path.',body:'A binary search tree keeps smaller keys in the left subtree and larger keys in the right. Search, insertion, and deletion follow a path whose cost depends on tree height h. Duplicate keys are ignored.',experiment:'Insert increasing values to create a tall tree. Compare its shape with an AVL tree.',insight:'Two-child deletion replaces a node with its in-order successor. An unbalanced BST can grow to height n.'},
 avl:{title:'AVL Tree',icon:'⋔',tag:'Trees',desc:'A search tree that keeps its balance, one rotation at a time.',time:'O(log n)',space:'O(n)',property:'Balanced',detail:'search / update',idea:'Stay balanced. Stay efficient.',body:'An AVL tree is a binary search tree whose left and right subtree heights differ by at most one at every node. Updates rebalance affected subtrees using left or right rotations. Each node displays its balance factor.',experiment:'Apply 30, 20, 10 to trigger a right rotation. Then try 30, 10, 20 for a double rotation.',insight:'BF = height(left) − height(right). Values −1, 0, and 1 mean a node is balanced.'},
 stack:{title:'Stacks',icon:'▱',tag:'Data structure',desc:'Last in, first out. Push an idea, then pop it back.',time:'O(1)',space:'O(n)',property:'LIFO',detail:'push / pop',idea:'The most recent comes first.',body:'A stack adds and removes values at the same end, called the top. Push places a value on top, pop removes it, and peek reads it without removing it. Think of undo history or nested function calls.',experiment:'Push three values. Predict the pop order, then check it one step at a time.',insight:'The bottom stays put while the top changes. Popping or peeking an empty stack is rejected.'},
 queue:{title:'Queues',icon:'⇥',tag:'Data structure',desc:'First in, first out. Give every value its turn.',time:'O(1)*',space:'O(n)',property:'FIFO',detail:'linked / ring buffer',idea:'A fair turn for every value.',body:'A queue adds values at the rear and removes them from the front. A linked queue or ring buffer supports O(1) enqueue and dequeue. This visual lab uses a JavaScript array; its front removal takes O(n).',experiment:'Enqueue three values and then dequeue twice. The earliest arrivals leave first.',insight:'Queues power breadth-first search. The visualization labels the front and rear so the direction is clear.'},
 hash:{title:'Hash Tables',icon:'#',tag:'Data structure',desc:'Turn a key into an address. See collisions and how to resolve them.',time:'O(1) avg',space:'O(n + m)',property:'12 buckets',detail:'O(n) worst case',idea:'A good address changes everything.',body:'The hash function maps a value to one of 12 slots using modulo. Chaining stores colliding values in a bucket. Linear probing looks for the next available slot and preserves tombstones after deletion.',experiment:'Insert 5, 17, and 29. They all hash to slot 5. Compare chaining with linear probing.',insight:'Negative values use normalized modulo. A deleted probe slot is marked with a tombstone, so searches can continue.'},
 graph:{title:'Graphs',icon:'⌘',tag:'Algorithms',desc:'Explore connections with BFS, DFS, and Dijkstra’s shortest paths.',time:'O(V + E)',space:'O(V + E)',property:'Undirected',detail:'BFS / DFS',idea:'Every connection tells a story.',body:'BFS explores in layers with a queue. DFS follows a path deeply using a stack. Dijkstra repeatedly settles the nearest reachable node and relaxes its edges. This lab accepts undirected graphs with positive integer edge weights.',experiment:'Add an isolated node to your graph. Traversal reaches only the start component, and Dijkstra leaves unreachable distances at ∞.',insight:'BFS finds shortest paths by edge count in unweighted graphs. Dijkstra considers the edge weights; this small implementation scans nodes in O(V² + E).'},
 dp:{title:'Dynamic Programming',icon:'▧',tag:'Algorithms',desc:'Solve it once. Reuse the answer. Watch a table build a solution.',time:'O(n)',space:'O(n)',property:'Tabulation',detail:'Fibonacci',idea:'Remember the work you’ve done.',body:'Dynamic programming solves overlapping subproblems once and stores their answers. Fibonacci fills a one-dimensional table. Longest Common Subsequence (LCS) fills a matrix of prefix comparisons in O(mn) time and space.',experiment:'Switch to LCS and compare ABCBDAB with BDCABA. A longest common subsequence has length 4.',insight:'Each highlighted cell depends on previously computed entries. The final LCS answer includes one possible subsequence.'}
};
const defaultValues=[42,18,65,30,82,50,24,72,38,56];
let key='bubble',model=[],frames=[],pointer=0,playing=false,timer=null,speed=1,frame=null,operation='sort',toastTimer;
const isSort=()=>key in sorts;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function halt(){clearTimeout(timer);timer=null;playing=false;updatePlayback();}
function updatePlayback(){ $('playButton').innerHTML=playing?'Ⅱ <span>Pause</span>':'▶︎ <span>Start</span>';$('playButton').setAttribute('aria-label',playing?'Pause animation':'Start animation');$('statusChip').classList.toggle('running',playing);$('prevButton').disabled=pointer<=0;$('stepButton').disabled=!!frames.length&&pointer>=frames.length-1;}
function info(){if(isSort()){const s=sorts[key];return {title:s[0],icon:'▥',tag:'Sorting',desc:s[1],time:s[2],space:s[3],property:s[4],detail:'worst-case time',idea:s[5],body:s[6],experiment:s[7],insight:s[8]};}return topics[key];}
const groups=[['DATA STRUCTURES',[['array','▦','Arrays'],['linked','⊷','Linked Lists'],['bst','⋔','Binary Search Tree'],['avl','⋔','AVL Tree'],['stack','▱','Stacks'],['queue','⇥','Queues'],['hash','#','Hash Tables']]],['ALGORITHMS',[['graph','⌘','Graphs'],['dp','▧','Dynamic Programming']]],['SORTING',[...Object.entries(sorts).map(([k,v])=>[k,'▥',v[0]])]]];
$('navigation').innerHTML=groups.map(([title,items])=>`<div class="nav-group-title">${title}</div>${items.map(([k,icon,label])=>`<a class="nav-item" href="#${k}" data-topic="${k}"><span class="nav-symbol">${icon}</span><span>${label}</span><span class="nav-arrow">${k===key?'›':''}</span></a>`).join('')}`).join('');
const field=(id,label,value,cls='grow',type='text')=>`<div class="field ${cls}"><label for="${id}">${label}</label><input type="${type}" id="${id}" value="${escape(value)}" autocomplete="off"></div>`;
const select=(id,label,options)=>`<div class="field grow"><label for="${id}">${label}</label><select id="${id}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div>`;
const button=(op,label)=>`<button class="op-button" data-op="${op}">${label}</button>`;
function chooseTopic(k){halt();key=(k in sorts||k in topics)?k:'bubble';frames=[];pointer=0;frame=null;operation=isSort()?'sort':key==='graph'?'bfs':key==='dp'?'compute':'search';
  const d=info();for(const [id,value] of Object.entries({topicTitle:d.title,topicIcon:d.icon,topicTag:d.tag,topicDescription:d.desc,learnTitle:d.idea,learnDescription:d.body,experimentText:d.experiment,insightText:d.insight}))$(id).textContent=value;
  $('breadcrumb').textContent=isSort()?'Sorting algorithms':key==='graph'||key==='dp'?'Algorithms':'Data structures';document.title=`${d.title} · DSA Studio`;
  document.querySelectorAll('.nav-item').forEach(el=>{el.classList.toggle('active',el.dataset.topic===key);el.querySelector('.nav-arrow').textContent=el.dataset.topic===key?'›':'';if(el.dataset.topic===key)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  $('metrics').innerHTML=[['◷','TIME COMPLEXITY',d.time,d.detail],['▱','SPACE COMPLEXITY',d.space,'storage'],['⊞','CHARACTERISTIC',d.property,''],['↳','LEARNING MODE','Step by step','interactive']].map(([i,l,v,s])=>`<div class="metric"><span class="metric-icon">${i}</span><div><div class="metric-label">${l}</div><div class="metric-value">${v}<small>${s}</small></div></div></div>`).join('');
  let inp='',ops='';
  if(key==='graph'){model=parseGraph('A,B,C,D,E,F','A-B:4,A-C:2,B-D:3,C-D:1,C-E:5,D-F:2,E-F:1');inp=field('nodesInput','NODES','A, B, C, D, E, F')+field('edgesInput','EDGES · A-B:WEIGHT','A-B:4, A-C:2, B-D:3, C-D:1, C-E:5, D-F:2, E-F:1');ops=field('startInput','START NODE','A','')+button('bfs','BFS')+button('dfs','DFS')+button('dijkstra','Dijkstra');}
  else if(key==='dp'){model=dpFrames('fibonacci',10)[0].data;inp=select('dpMode','PROBLEM',[['fibonacci','Fibonacci'],['lcs','Longest Common Subsequence']])+field('nInput','N · 2–18',10,'','number');ops=button('compute','Build table');}
  else{let values=isSort()?defaultValues:['bst','avl'].includes(key)?[45,25,65,15,35,55,75]:key==='stack'?[12,24,36,48]:key==='queue'?[12,24,36,48,60]:key==='hash'?[5,17,8,20,10]:[12,23,34,45,56];
    model=key==='bst'||key==='avl'?makeTree(values,key==='avl'):key==='hash'?Array.from({length:12},()=>[]):[...values];if(key==='hash')for(const v of values)model=hashFrames(model,'insert',v).at(-1).data;
    inp=field('valuesInput',isSort()?'ARRAY VALUES · 5–24 INTEGERS':'VALUES · COMMA SEPARATED',values.join(', '));
    if(key==='linked')inp+=select('listType','LIST TYPE',[['singly','Singly linked'],['doubly','Doubly linked'],['circular','Circular linked']]);
    if(key==='hash')inp+=select('hashMethod','COLLISION HANDLING',[['chaining','Chaining'],['probing','Linear probing']]);
    if(!isSort()){ops=field('valueInput','VALUE',key==='bst'||key==='avl'?40:key==='hash'?29:23,'','number');if(['array','linked'].includes(key))ops+=field('indexInput','POSITION',2,'','number');
      if(key==='array')ops+=button('insert','Insert')+button('delete','Delete')+button('update','Update')+button('search','Search')+button('reverse','Reverse');
      if(key==='linked')ops+=button('insertStart','+ Start')+button('insertEnd','+ End')+button('insert','+ Position')+button('deleteStart','− Start')+button('deleteEnd','− End')+button('delete','− Position')+button('search','Search')+button('reverse','Reverse')+button('sort','Sort');
      if(key==='stack')ops+=button('push','Push')+button('pop','Pop')+button('peek','Peek')+button('isEmpty','Is empty?');
      if(key==='queue')ops+=button('enqueue','Enqueue')+button('dequeue','Dequeue')+button('peek','Front')+button('isEmpty','Is empty?');
      if(['bst','avl'].includes(key))ops+=button('insert','Insert')+button('delete','Delete')+button('search','Search')+button('inorder','In-order');
      if(key==='hash')ops+=button('insert','Insert')+button('search','Search')+button('delete','Delete');
    }
  }
  $('inputArea').innerHTML=inp+'<button class="outline-button" id="applyButton">Apply</button><button class="outline-button" id="randomButton">⤨ Random</button>';$('operations').innerHTML=ops;
  $('applyButton').onclick=applyInputs;$('randomButton').onclick=randomize;$('operations').onclick=e=>{const b=e.target.closest('[data-op]');if(b)runOperation(b.dataset.op);};
  $('listType')?.addEventListener('change',()=>{halt();draw(frame||{data:model,active:[]});});
  $('hashMethod')?.addEventListener('change',()=>applyInputs());
  $('dpMode')?.addEventListener('change',()=>{halt();frames=[];pointer=0;frame=null;const mode=$('dpMode').value;$('nInput')?.parentElement.remove();$('sInput')?.parentElement.remove();$('tInput')?.parentElement.remove();const fields=mode==='fibonacci'?field('nInput','N · 2–18',10,'','number'):field('sInput','STRING A · MAX 8 CHARS','AGGTAB')+field('tInput','STRING B · MAX 8 CHARS','GXTXAYB');$('applyButton').insertAdjacentHTML('beforebegin',fields);applyInputs();});
  setCode(operation);draw({data:model,active:[]});updateStatus('Ready');$('stepMessage').textContent='Press Start to see the algorithm in action, or pick an operation below the input.';$('stepTitle').textContent='Let’s break it down';$('sidebar').classList.remove('open');
}
function parseValues(text,min=0,max=18){const pieces=text.trim()?text.trim().split(/[\s,]+/):[];if(pieces.length<min||pieces.length>max)throw Error(`Please enter ${min}–${max} integers, separated by commas.`);if(pieces.some(p=>! /^-?\d+$/.test(p)))throw Error('Use whole numbers separated by commas.');const a=pieces.map(Number);if(a.some(v=>!Number.isSafeInteger(v)||v< -99||v>999))throw Error('Values must be integers from −99 to 999.');if(isSort()&&['counting','radix'].includes(key)&&a.some(v=>v<0))throw Error('This algorithm needs nonnegative values (0–999).');return a;}
function applyInputs(){try{let next;if(key==='graph')next=parseGraph($('nodesInput').value,$('edgesInput').value);else if(key==='dp'){const mode=$('dpMode').value;if(mode==='fibonacci'){const n=integer('nInput');if(n<2||n>18)throw Error('Choose an integer N from 2 to 18.');next=dpFrames(mode,n)[0].data;}else{const s=$('sInput').value.toUpperCase(),t=$('tInput').value.toUpperCase();if(!s.length||!t.length||s.length>8||t.length>8||! /^[A-Z]+$/.test(s+t))throw Error('Enter 1–8 letters A–Z in each string.');$('sInput').value=s;$('tInput').value=t;next=dpFrames(mode,0,s,t)[0].data;}}
  else{const a=parseValues($('valuesInput').value,isSort()?5:0,isSort()?24:key==='linked'?14:['bst','avl'].includes(key)?20:18);if(['bst','avl'].includes(key))next=makeTree(a,key==='avl');else if(key==='hash'){const method=$('hashMethod').value;next=method==='chaining'?Array.from({length:12},()=>[]):Array(12).fill(null);for(const v of a)next=hashFrames(next,'insert',v,method).at(-1).data;}else next=a;}
  halt();model=next;frames=[];pointer=0;frame=null;setCode(operation);draw({data:model,active:[]});updateStatus('Ready');$('stepTitle').textContent='Your example is ready';$('stepMessage').textContent='Input applied. Press Start or choose an operation to explore it.';
 }catch(e){toast(e.message);}}
function randomize(){halt();if(key==='graph'){const possible=[['A','B'],['A','C'],['B','D'],['C','D'],['C','E'],['D','F'],['E','F'],['B','E']];$('nodesInput').value='A, B, C, D, E, F';$('edgesInput').value=possible.filter(()=>Math.random()>.15).map(([a,b])=>`${a}-${b}:${1+Math.floor(Math.random()*9)}`).join(', ');}
 else if(key==='dp'){if($('dpMode').value==='fibonacci')$('nInput').value=5+Math.floor(Math.random()*14);else{const chars='ABCDEF';for(const id of ['sInput','tInput'])$(id).value=Array.from({length:6},()=>chars[Math.floor(Math.random()*chars.length)]).join('');}}
 else $('valuesInput').value=Array.from({length:isSort()?10:key==='stack'?5:key==='hash'?7:7},()=>10+Math.floor(Math.random()*85)).join(', ');applyInputs();}
function integer(id){const str=$(id)?.value?.trim();if(!str||! /^-?\d+$/.test(str))throw Error('Enter a whole number for '+(id==='indexInput'?'position':'value')+'.');const value=Number(str);if(value< -99||value>999)throw Error('Value must be from −99 to 999.');return value;}
function buildFrames(op){if(isSort())return sortFrames(model,key);if(key==='graph')return graphFrames(model,op,$('startInput').value.trim().toUpperCase());if(key==='dp')return $('dpMode').value==='fibonacci'?dpFrames('fibonacci',integer('nInput')):dpFrames('lcs',0,$('sInput').value.toUpperCase(),$('tInput').value.toUpperCase());
  let v=['reverse','sort','peek','isEmpty','pop','dequeue','delete','deleteStart','deleteEnd','inorder'].includes(op)?0:integer('valueInput');
  if(['bst','avl'].includes(key)){if(op==='delete')v=integer('valueInput');if(op==='insert'&&treeValues(model).length>=20&&!treeValues(model).includes(v))throw Error('Tree limit is 20 nodes. Delete a node first.');return treeFrames(model,op,v,key==='avl');}
  if(key==='hash'){v=integer('valueInput');return hashFrames(model,op,v,$('hashMethod').value);}
  let index=$('indexInput')?integer('indexInput'):0,normalized=op;
  if(['insertStart','insertEnd','push','enqueue'].includes(op)){normalized='insert';index=op==='insertStart'?0:model.length;}
  if(['deleteStart','deleteEnd','pop','dequeue'].includes(op)){normalized='delete';index=['deleteStart','dequeue'].includes(op)?0:model.length-1;}
  if(normalized==='insert'&&model.length>=(key==='linked'?14:key==='stack'?8:18))throw Error(`This view is full (${model.length} values). Delete or remove a value first.`);
  return linearFrames(model,normalized,v,index,key);
}
function runOperation(op){try{if(key==='dp'){const mode=$('dpMode').value;if(mode==='fibonacci'){const n=integer('nInput');if(n<2||n>18)throw Error('Choose N from 2 to 18.');}else{const s=$('sInput').value,t=$('tInput').value;if(!s.length||!t.length||s.length>8||t.length>8||! /^[A-Za-z]+$/.test(s+t))throw Error('Enter 1–8 letters A–Z in each string.');}}
  const next=buildFrames(op);halt();operation=op;frames=next;pointer=0;setCode(op);showFrame();playing=true;updatePlayback();updateStatus('Running');schedule();}catch(e){toast(e.message);}}
function schedule(){clearTimeout(timer);if(!playing)return;timer=setTimeout(()=>{if(!playing)return;if(pointer<frames.length-1){pointer++;showFrame();if(pointer===frames.length-1){halt();updateStatus('Complete');syncValues();}else schedule();}else{halt();updateStatus('Complete');}},650/speed);}
function showFrame(){if(!frames.length)return;frame=frames[pointer];model=clone(frame.data);draw(frame);$('stepMessage').textContent=frame.message;$('stepTitle').textContent=pointer===frames.length-1?'You’ve got it.':`Step ${pointer+1} · ${info().title}`;document.querySelectorAll('.code-line').forEach((el,i)=>el.classList.toggle('highlight',i+1===(frame.line||1)));$('stepLabel').textContent=`STEP ${pointer+1} / ${frames.length}`;$('progressFill').style.width=`${100*(pointer+1)/frames.length}%`;$('runStats').textContent=frame.comparisons===undefined?'Follow the highlighted step':`${frame.comparisons} comparisons · ${frame.writes||0} writes`;updatePlayback();if(pointer===frames.length-1)syncValues();}
function syncValues(){if(!$('valuesInput'))return;let a=['bst','avl'].includes(key)?null:key==='hash'?($('hashMethod').value==='chaining'?model.flat():model.filter(v=>typeof v==='number')):model;if(a)$('valuesInput').value=a.join(', ');}
function updateStatus(s){if(key==='dp'){const isLcs=$('dpMode')?.value==='lcs';const values=$('metrics').querySelectorAll('.metric-value');values[0].innerHTML=isLcs?'O(mn)<small>LCS</small>':'O(n)<small>Fibonacci</small>';values[1].innerHTML=(isLcs?'O(mn)':'O(n)')+'<small>storage</small>';}if(key==='graph'){const values=$('metrics').querySelectorAll('.metric-value');values[0].innerHTML=operation==='dijkstra'?'O(V² + E)<small>Dijkstra</small>':'O(V + E)<small>BFS / DFS</small>';} $('statusChip').textContent=s;if(!frames.length){$('stepLabel').textContent='STEP 0 / 0';$('progressFill').style.width='0%';$('runStats').textContent='Ready when you are';}updatePlayback();}
$('playButton').onclick=()=>{if(playing){halt();updateStatus('Paused');return;}if(!frames.length){runOperation(isSort()?'sort':key==='graph'?'bfs':key==='dp'?'compute':key==='stack'||key==='queue'?'peek':'search');return;}if(pointer>=frames.length-1){pointer=0;showFrame();}playing=true;updateStatus('Running');schedule();};
$('stopButton').onclick=()=>{halt();updateStatus('Stopped');syncValues();};
$('stepButton').onclick=()=>{if(!frames.length){runOperation(isSort()?'sort':key==='graph'?'bfs':key==='dp'?'compute':key==='stack'||key==='queue'?'peek':'search');halt();updateStatus('Paused');return;}halt();pointer=Math.min(frames.length-1,pointer+1);showFrame();updateStatus(pointer===frames.length-1?'Complete':'Paused');};
$('prevButton').onclick=()=>{halt();pointer=Math.max(0,pointer-1);showFrame();updateStatus('Paused');};
$('resetButton').onclick=()=>{halt();if(frames.length){pointer=0;showFrame();syncValues();}updateStatus('Ready');};
$('speedInput').oninput=e=>{speed=Number(e.target.value);$('speedLabel').textContent=`${speed}×`;if(playing)schedule();};
function setCode(op){let code;if(isSort())code=sorts[key][9];else if(key==='graph')code=op==='dijkstra'?['distance[start] = 0; others = ∞','settle nearest unvisited node','relax each neighbor via this node','repeat until no reachable node','return shortest distances']:['frontier = [start]; seen = {start}',`take next node from ${op==='dfs'?'stack':'queue'}`,'add unseen neighbors to frontier','repeat until frontier is empty','return traversal order'];else if(key==='dp')code=$('dpMode')?.value==='lcs'?['dp[0][*] = dp[*][0] = 0','if a[i−1] == b[j−1]: diagonal + 1','else: max(top, left)','return dp[m][n]; trace a sequence','each cell reuses solved prefixes']:['dp[0] = 0; dp[1] = 1','for i from 2 through n:','  dp[i] = dp[i−1] + dp[i−2]','return dp[n]','each subproblem is solved once'];else if(['bst','avl'].includes(key))code=op==='inorder'?['traverse(node):','  left; visit node; right','  recurse through each subtree','return values in ascending order','']:['start at the root','compare key; follow left or right',op==='search'?'if key matches: found':`${op} the matching position` ,key==='avl'?'restore balance with rotations':'return the updated tree',''];else if(key==='hash')code=['index = normalized_mod(key, 12)',$('hashMethod')?.value==='probing'?'probe until found or empty':'follow the bucket chain',`${op} the key at its location`,'return result',''];else if(op==='sort')code=sorts.insertion[9];else if(op==='reverse')code=['left = 0; right = length − 1','while left < right:','  swap; left++; right--','return reversed_sequence',''];else{const insertion=['insert','insertStart','insertEnd','push','enqueue'].includes(op),deletion=['delete','deleteStart','deleteEnd','pop','dequeue'].includes(op);code=insertion?['locate the insertion position','shift values / reconnect links',`insert value ${op==='push'?'at top':op==='enqueue'?'at rear':'at position'}`,'return updated_structure','']:deletion?['check structure is not empty','locate value to remove','remove; shift / reconnect links','return updated_structure','']:op==='isEmpty'?['read the structure length','compare length with zero','return length == 0','','']:op==='peek'?['check structure is not empty','locate top / front','return value without removing it','','']:op==='update'?['locate the requested index','check index is in bounds','replace value at index','return updated_array','']:['start at the first value','compare each value with target','continue to the next position','return found position or not found',''];}
 $('codeFilename').textContent=(isSort()?sorts[key][0].toLowerCase().replaceAll(' ','_'):key+'_'+op)+'.py';$('codeDisplay').innerHTML=code.map((s,i)=>`<div class="code-line"><span class="line-number">${String(i+1).padStart(2,'0')}</span><span>${escape(s)}</span></div>`).join('');}
function draw(f){const stage=$('stage'),a=f.data,active=f.active||[],previous=new Map([...stage.querySelectorAll('[data-visual-key]')].map(el=>[el.dataset.visualKey,el.getBoundingClientRect()]));stage.innerHTML='';stage.style.height='';stage.style.minWidth='';$('stageHint').textContent=isSort()?'Values are shown below each bar':'Positions start at zero';let count=isSort()||Array.isArray(a)?a.length:0;if(['bst','avl'].includes(key))count=treeValues(a).length;if(key==='hash')count=$('hashMethod').value==='chaining'?a.flat().length:a.filter(v=>typeof v==='number').length;if(key==='graph')count=a.nodes.length;if(key==='dp')count=Array.isArray(a)?a.length:(a.s.length+1)*(a.t.length+1);$('itemCount').textContent=`${count} ${key==='graph'||['bst','avl','linked'].includes(key)?'nodes':key==='dp'?'cells':'elements'}`;
 if(isSort()){const max=Math.max(1,...a.map(Math.abs)),seen={};stage.innerHTML=`<div class="bars">${a.map((v,i)=>`<div class="bar-container" data-visual-key="bar_${v}_${seen[v]=(seen[v]||0)+1}"><div class="bar ${active.includes(i)?'active':(f.sorted||[]).includes(i)?'done':''}" style="height:${Math.max(8,Math.abs(v)/max*90)}%"></div><span class="bar-value">${v}</span><span class="bar-index">${i}</span></div>`).join('')}</div>`;}
 else if(key==='linked')drawLinked(a,active);
 else if(['bst','avl'].includes(key))drawTree(a,active);
 else if(key==='hash'){stage.innerHTML=`<div class="hash-grid">${a.map((v,i)=>`<div class="hash-cell ${active.includes(i)?'active':''}"><span class="hash-index">${i}</span><span class="hash-chain">${Array.isArray(v)?v.map(escape).join(' → ')||'∅':v===null?'∅':v==='deleted'?'† deleted':escape(v)}</span></div>`).join('')}</div>`;$('stageHint').textContent='h(key) = normalized key % 12';}
 else if(key==='graph')drawGraph(f);
 else if(key==='dp'&&!Array.isArray(a)){stage.innerHTML=`<table class="dp-table" aria-label="Longest common subsequence table"><thead><tr><th></th><th>∅</th>${[...a.t].map(c=>`<th>${escape(c)}</th>`).join('')}</tr></thead><tbody>${a.matrix.map((row,i)=>`<tr><th>${i===0?'∅':escape(a.s[i-1])}</th>${row.map((v,j)=>`<td class="${f.cell?.[0]===i&&f.cell?.[1]===j?'active':''}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;$('stageHint').textContent='Rows = string A · columns = string B';}
 else if(key==='stack'){stage.innerHTML=`<div class="stack-stage">${a.length?a.map((v,i)=>`<div class="stack-item ${active.includes(i)?'active':''}">${v}${i===a.length-1?' ← TOP':''}</div>`).join(''):'<div class="empty-state">Empty stack</div>'}</div>`;}
 else if(key==='queue'){stage.style.minWidth=`${Math.max(280,a.length*55+50)}px`;stage.innerHTML=a.length?`<div class="queue-stage">${a.map((v,i)=>`<div class="array-node ${active.includes(i)?'active':''}">${v}<small>${i===0?'FRONT':i===a.length-1?'REAR':i}</small></div>`).join('')}</div>`:'<div class="empty-state">Empty queue · enqueue to begin</div>';}
 else{if(key!=='dp')stage.style.minWidth=`${Math.max(280,a.length*57+20)}px`;stage.innerHTML=a.length?`<div class="array-boxes ${key==='dp'?'dp-nodes':''}">${a.map((v,i)=>`<div class="array-node ${active.includes(i)?'active':''} ${key==='dp'&&v!==null?'done':''}">${v??'·'}<small>${key==='dp'?'F('+i+')':i}</small></div>`).join('')}</div>`:'<div class="empty-state">Empty array · insert a value to begin</div>';}
 if(window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches){gsap.from(stage.querySelectorAll('.active'),{opacity:.4,duration:.22});stage.querySelectorAll('[data-visual-key]').forEach(el=>{const before=previous.get(el.dataset.visualKey);if(before){const now=el.getBoundingClientRect();gsap.from(el,{x:before.x-now.x,y:before.y-now.y,duration:Math.min(.4,.55/speed),ease:'power2.out'});}});}
}
function svgBase(width,height){const svg=d3.select('#stage').append('svg').attr('viewBox',`0 0 ${width} ${height}`).attr('role','img');return svg;}
function drawLinked(a,active){const n=a.length,w=Math.max(400,n*96+40),type=$('listType').value;const svg=svgBase(w,230);svg.style('min-width',`${w}px`);$('stage').style.minWidth=`${w}px`;svg.append('title').text(`${type} linked list: ${a.join(', ')}`);const defs=svg.append('defs');defs.append('marker').attr('id','list-arrow').attr('viewBox','0 -4 8 8').attr('refX',7).attr('markerWidth',6).attr('markerHeight',6).attr('orient','auto').append('path').attr('d','M0,-4L8,0L0,4').attr('fill','#91aa79');const group=svg.append('g').attr('transform',`translate(${(w-n*96+40)/2},100)`);
 for(let i=0;i<n-1;i++){group.append('path').attr('d',`M${i*96+54},${type==='doubly'?-7:0}L${(i+1)*96-9},${type==='doubly'?-7:0}`).attr('stroke','#8fa975').attr('stroke-width',1.6).attr('marker-end','url(#list-arrow)');if(type==='doubly')group.append('path').attr('d',`M${(i+1)*96-9},9L${i*96+54},9`).attr('stroke','#a9bd97').attr('stroke-width',1.5).attr('marker-end','url(#list-arrow)');}
 if(type==='circular'&&n){group.append('path').attr('d',`M${(n-1)*96+24},24V65H24V27`).attr('stroke','#8fa975').attr('fill','none').attr('stroke-width',1.6).attr('marker-end','url(#list-arrow)');group.append('text').attr('x',n*48-25).attr('y',82).attr('fill','#9caf88').attr('font-size',8).text('tail → head');}
 a.forEach((v,i)=>{const g=group.append('g').attr('transform',`translate(${i*96},0)`).attr('data-visual-key',`list_${v}_${i}`);g.append('rect').attr('x',-4).attr('y',-25).attr('width',57).attr('height',50).attr('rx',7).attr('fill',active.includes(i)?'#f3d59c':['#d3e3be','#e4ddc5','#cee0d7'][i%3]).attr('stroke',active.includes(i)?'#d5a35a':'#b0c59c');g.append('text').attr('x',24).attr('y',4).attr('text-anchor','middle').attr('class','tree-label').text(v);g.append('text').attr('x',24).attr('y',-39).attr('text-anchor','middle').attr('font-size',8).attr('fill','#8da079').text(i===0?'HEAD':i===n-1?'TAIL':`node ${i}`);});if(!n)svg.append('text').attr('x',w/2).attr('y',120).attr('text-anchor','middle').attr('fill','#91a57c').text('Empty list · insert a node to begin');$('stageHint').textContent='Arrows show the next-node links';}
function drawTree(root,active){if(!root){$('stage').innerHTML='<div class="empty-state">Empty tree · insert a node to begin</div>';return;}const h=d3.hierarchy(root,n=>[n.left?{...n.left,side:'left'}:null,n.right?{...n.right,side:'right'}:null].filter(Boolean));
 // In-order ranks keep left/right placement correct even with a single child.
 const ordered=treeValues(root),w=Math.max(440,ordered.length*51+40),ht=Math.max(260,height(root)*66+25);h.each(n=>{n.x=30+ordered.indexOf(n.data.value)*(w-60)/Math.max(1,ordered.length-1);if(ordered.length===1)n.x=w/2;n.y=35+n.depth*65;});const svg=svgBase(w,ht);svg.style('min-width',`${w}px`);$('stage').style.height=`${ht}px`;$('stage').style.minWidth=`${w}px`;svg.append('title').text(`${key==='avl'?'AVL':'Binary search'} tree. Nodes: ${ordered.join(', ')}.`);svg.selectAll('path.tree-edge').data(h.links()).join('path').attr('class','tree-edge').attr('d',d=>`M${d.source.x},${d.source.y+20} C${d.source.x},${d.source.y+39} ${d.target.x},${d.target.y-39} ${d.target.x},${d.target.y-20}`).attr('fill','none').attr('stroke','#a3b98b').attr('stroke-width',1.7);const g=svg.selectAll('g.tree-node').data(h.descendants()).join('g').attr('class','tree-node').attr('transform',d=>`translate(${d.x},${d.y})`).attr('data-visual-key',d=>`tree_${d.data.value}`);g.append('circle').attr('r',20).attr('fill',d=>active.includes(d.data.value)?'#f0d29b':d.depth%2?'#dbe8c9':'#c7dfb2').attr('stroke',d=>active.includes(d.data.value)?'#d5a65f':'#9cbb82').attr('stroke-width',1.2);g.append('text').attr('class','tree-label').attr('text-anchor','middle').attr('dy',4).text(d=>d.data.value);if(key==='avl')g.append('text').attr('class','tree-balance').attr('text-anchor','middle').attr('y',-27).text(d=>`BF ${balance(d.data)}`);$('stageHint').textContent=key==='avl'?'BF = left height − right height':'Left < node < right';}
function drawGraph(f){const a=f.data,w=500,ht=265,positions={};a.nodes.forEach((n,i)=>{let angle=-Math.PI/2+2*Math.PI*i/a.nodes.length;positions[n]={x:w/2+Math.cos(angle)*165,y:120+Math.sin(angle)*88};});const svg=svgBase(w,ht);svg.append('title').text(`Undirected graph with ${a.nodes.length} nodes and ${a.edges.length} edges.`);const lines=svg.append('g');for(const e of a.edges){const p=positions[e.a],q=positions[e.b],hot=f.edge&&f.edge.includes(e.a)&&f.edge.includes(e.b);lines.append('line').attr('x1',p.x).attr('y1',p.y).attr('x2',q.x).attr('y2',q.y).attr('stroke',hot?'#d5a259':'#b7c8a6').attr('stroke-width',hot?3:1.5);lines.append('text').attr('x',(p.x+q.x)/2).attr('y',(p.y+q.y)/2-4).attr('class','edge-label').attr('text-anchor','middle').text(e.weight);}for(const n of a.nodes){const p=positions[n],hot=(f.active||[]).includes(n),done=(f.visited||[]).includes(n);svg.append('circle').attr('cx',p.x).attr('cy',p.y).attr('r',20).attr('fill',hot?'#f1d39c':done?'#91b875':'#e5edda').attr('stroke',hot?'#d2a15a':done?'#6e9753':'#acc396').attr('stroke-width',1.5);svg.append('text').attr('x',p.x).attr('y',p.y+4).attr('class','graph-node-text').attr('text-anchor','middle').text(n);}if(f.dist&&operation==='dijkstra')$('stage').insertAdjacentHTML('beforeend',`<div class="graph-results">${a.nodes.map(n=>`<span>${n}: ${f.dist[n]??'∞'}</span>`).join('')}</div>`);$('stageHint').textContent=operation==='dijkstra'?'Distances shown from start node':'Undirected · weighted edges';}
$('guideButton').onclick=()=>$('learnSection').scrollIntoView({behavior:'smooth'});$('helpButton').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('menuToggle').onclick=()=>$('sidebar').classList.toggle('open');
window.addEventListener('hashchange',()=>chooseTopic(location.hash.slice(1)));document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)||$('helpDialog').open)return;if(e.code==='Space'){e.preventDefault();$('playButton').click();}if(e.key==='ArrowRight'){e.preventDefault();$('stepButton').click();}if(e.key.toLowerCase()==='s')$('stopButton').click();if(e.key.toLowerCase()==='r')$('resetButton').click();});
